## Pulumi.yaml

```yaml
name: webapp-infra
runtime: nodejs
description: Stateless web app infrastructure (S3 + RDS + IAM)
```

## Stack configs

**Pulumi.dev.yaml**

```yaml
config:
  aws:region: us-east-1
  webapp-infra:environment: dev
  webapp-infra:dbInstanceClass: db.t3.micro
  webapp-infra:dbMultiAz: false
  webapp-infra:dbAllocatedStorage: "20"
  webapp-infra:dbPassword:
    secure: AAABANt6...  # encrypted via Pulumi secrets provider
  webapp-infra:bucketReplicationRegion: ""   # no replication in dev
```

**Pulumi.prod.yaml**

```yaml
config:
  aws:region: us-east-1
  webapp-infra:environment: prod
  webapp-infra:dbInstanceClass: db.t3.medium
  webapp-infra:dbMultiAz: true
  webapp-infra:dbAllocatedStorage: "50"
  webapp-infra:dbPassword:
    secure: AAABAMx4...
  webapp-infra:bucketReplicationRegion: us-west-2
```

## components/bucket.ts

```typescript
import * as aws from "@pulumi/aws";
import * as pulumi from "@pulumi/pulumi";

export interface BucketArgs {
  environment: string;
  replicationRegion?: string; // set only for prod
}

export class AssetBucket extends pulumi.ComponentResource {
  public readonly bucket: aws.s3.BucketV2;
  public readonly bucketName: pulumi.Output<string>;

  constructor(name: string, args: BucketArgs, opts?: pulumi.ComponentResourceOptions) {
    super("webapp:infra:AssetBucket", name, {}, opts);

    this.bucket = new aws.s3.BucketV2(`${name}-assets`, {
      tags: { Environment: args.environment },
    }, { parent: this });

    // Versioning — required in all environments
    new aws.s3.BucketVersioningV2(`${name}-versioning`, {
      bucket: this.bucket.id,
      versioningConfiguration: { status: "Enabled" },
    }, { parent: this });

    // SSE (AES-256), required in all environments
    new aws.s3.BucketServerSideEncryptionConfigurationV2(`${name}-sse`, {
      bucket: this.bucket.id,
      rules: [{
        applyServerSideEncryptionByDefault: { sseAlgorithm: "AES256" },
      }],
    }, { parent: this });

    // Block all public access
    new aws.s3.BucketPublicAccessBlock(`${name}-pab`, {
      bucket: this.bucket.id,
      blockPublicAcls: true,
      blockPublicPolicy: true,
      ignorePublicAcls: true,
      restrictPublicBuckets: true,
    }, { parent: this });

    // Cross-region replication (prod only)
    if (args.replicationRegion) {
      const replica = new aws.s3.BucketV2(`${name}-replica`, {
        region: args.replicationRegion,
        tags: { Environment: args.environment, Role: "replica" },
      }, { parent: this });

      new aws.s3.BucketVersioningV2(`${name}-replica-versioning`, {
        bucket: replica.id,
        versioningConfiguration: { status: "Enabled" },
      }, { parent: this });

      const replicationRole = new aws.iam.Role(`${name}-replication-role`, {
        assumeRolePolicy: aws.iam.assumeRolePolicyForPrincipal({
          Service: "s3.amazonaws.com",
        }),
      }, { parent: this });

      new aws.iam.RolePolicy(`${name}-replication-policy`, {
        role: replicationRole.name,
        policy: this.bucket.arn.apply(arn =>
          JSON.stringify({
            Version: "2012-10-17",
            Statement: [{
              Effect: "Allow",
              Action: [
                "s3:GetReplicationConfiguration",
                "s3:ListBucket",
              ],
              Resource: arn,
            }, {
              Effect: "Allow",
              Action: [
                "s3:GetObjectVersionForReplication",
                "s3:GetObjectVersionAclForReplication",
                "s3:ReplicateObject",
                "s3:ReplicateDelete",
                "s3:ReplicateTags",
              ],
              Resource: pulumi.interpolate`${arn}/*`,
            }, {
              Effect: "Allow",
              Action: ["s3:ReplicateObject", "s3:ReplicateTags"],
              Resource: pulumi.interpolate`${replica.arn}/*`,
            }],
          })
        ),
      }, { parent: this });

      new aws.s3.BucketReplicationConfigV2(`${name}-replication`, {
        bucket: this.bucket.id,
        role: replicationRole.arn,
        rules: [{
          id: "replicate-all",
          status: "Enabled",
          priority: 1,
          deleteMarkerReplication: { status: "Disabled" },
          filter: {},
          destination: { bucket: replica.arn },
        }],
      }, { parent: this });
    }

    this.bucketName = this.bucket.bucket;
    this.registerOutputs();
  }
}
```

## components/database.ts

```typescript
import * as aws from "@pulumi/aws";
import * as pulumi from "@pulumi/pulumi";

export interface DatabaseArgs {
  environment: string;
  instanceClass: string; // db.t3.micro (dev) | db.t3.medium (prod)
  multiAz: boolean;
  allocatedStorage: number;
  masterPassword: pulumi.Input<string>; // secret from config
}

export class PostgresDatabase extends pulumi.ComponentResource {
  public readonly instance: aws.rds.Instance;
  public readonly connectionString: pulumi.Output<string>;

  constructor(name: string, args: DatabaseArgs, opts?: pulumi.ComponentResourceOptions) {
    super("webapp:infra:PostgresDatabase", name, {}, opts);

    const username = "webapp_admin";

    this.instance = new aws.rds.Instance(`${name}-pg`, {
      engine: "postgres",
      engineVersion: "16.3",
      instanceClass: args.instanceClass,
      allocatedStorage: args.allocatedStorage,
      dbName: "webapp",
      username,
      password: args.masterPassword,
      multiAz: args.multiAz,
      // Security requirements
      deletionProtection: true,
      publiclyAccessible: false,
      backupRetentionPeriod: 7,
      storageEncrypted: true,
      skipFinalSnapshot: args.environment === "dev",
      finalSnapshotIdentifier: args.environment === "prod" ? `${name}-final` : undefined,
      tags: { Environment: args.environment },
    }, { parent: this });

    // Allow destroy in dev by opting out of deletion protection per stack is not
    // allowed by spec — deletion protection stays on; disable via stack config if needed.

    this.connectionString = pulumi.interpolate`postgresql://${username}:${args.masterPassword}@${this.instance.endpoint}/webapp`;
    this.registerOutputs({ connectionString: this.connectionString });
  }
}
```

## components/iam.ts

```typescript
import * as aws from "@pulumi/aws";
import * as pulumi from "@pulumi/pulumi";

export interface ServiceAccountIamArgs {
  environment: string;
  bucketArn: pulumi.Input<string>;
  oidcProviderArn?: pulumi.Input<string>; // prod: EKS OIDC trust
  oidcProviderUrl?: pulumi.Input<string>;
}

export class ServiceAccountIam extends pulumi.ComponentResource {
  public readonly role: aws.iam.Role;

  constructor(name: string, args: ServiceAccountIamArgs, opts?: pulumi.ComponentResourceOptions) {
    super("webapp:infra:ServiceAccountIam", name, {}, opts);

    // Trust policy: dev = current account (programmatic), prod = OIDC federated role
    const trustPolicy = args.oidcProviderUrl
      ? pulumi.interpolate`{
          "Version": "2012-10-17",
          "Statement": [{
            "Effect": "Allow",
            "Action": "sts:AssumeRoleWithWebIdentity",
            "Principal": { "Federated": "${args.oidcProviderArn}" },
            "Condition": {
              "StringEquals": {
                "${args.oidcProviderUrl}:sub": "system:serviceaccount:webapp:webapp-sa"
              }
            }
          }]
        }`
      : aws.iam.assumeRolePolicyForPrincipal({ Service: "ec2.amazonaws.com" });

    this.role = new aws.iam.Role(`${name}-sa-role`, {
      assumeRolePolicy: trustPolicy,
      tags: { Environment: args.environment },
    }, { parent: this });

    // Least privilege: specific bucket actions only — no wildcards
    new aws.iam.RolePolicy(`${name}-sa-policy`, {
      role: this.role.name,
      policy: pulumi.output(args.bucketArn).apply(bucketArn =>
        JSON.stringify({
          Version: "2012-10-17",
          Statement: [
            {
              Effect: "Allow",
              Action: [
                "s3:GetObject",
                "s3:PutObject",
                "s3:DeleteObject",
                "s3:ListBucket",
                "s3:GetBucketLocation",
              ],
              Resource: [bucketArn, `${bucketArn}/*`],
            },
          ],
        })
      ),
    }, { parent: this });

    this.registerOutputs();
  }
}
```

## components/webapp.ts — the main ComponentResource

```typescript
import * as pulumi from "@pulumi/pulumi";
import { AssetBucket } from "./bucket";
import { PostgresDatabase } from "./database";
import { ServiceAccountIam } from "./iam";

export interface WebAppInfraArgs {
  environment: "dev" | "prod";
  dbInstanceClass: string;
  dbMultiAz: boolean;
  dbAllocatedStorage: number;
  dbPassword: pulumi.Input<string>;
  bucketReplicationRegion?: string;
  oidcProviderArn?: pulumi.Input<string>;
  oidcProviderUrl?: pulumi.Input<string>;
}

export class WebAppInfra extends pulumi.ComponentResource {
  public readonly bucketName: pulumi.Output<string>;
  public readonly dbEndpoint: pulumi.Output<string>;
  public readonly saRoleArn: pulumi.Output<string>;

  constructor(name: string, args: WebAppInfraArgs, opts?: pulumi.ComponentResourceOptions) {
    super("webapp:infra:WebAppInfra", name, {}, opts);

    const bucket = new AssetBucket(`${name}-assets`, {
      environment: args.environment,
      replicationRegion: args.bucketReplicationRegion,
    }, { parent: this });

    const db = new PostgresDatabase(`${name}-db`, {
      environment: args.environment,
      instanceClass: args.dbInstanceClass,
      multiAz: args.dbMultiAz,
      allocatedStorage: args.dbAllocatedStorage,
      masterPassword: args.dbPassword,
    }, { parent: this });

    const iam = new ServiceAccountIam(`${name}-sa`, {
      environment: args.environment,
      bucketArn: bucket.bucket.arn,
      oidcProviderArn: args.oidcProviderArn,
      oidcProviderUrl: args.oidcProviderUrl,
    }, { parent: this, dependsOn: [bucket] });

    this.bucketName = bucket.bucketName;
    this.dbEndpoint = db.instance.address;
    this.saRoleArn = iam.role.arn;
    this.registerOutputs();
  }
}
```

## index.ts

```typescript
import * as pulumi from "@pulumi/pulumi";
import { WebAppInfra } from "./components/webapp";

const config = new pulumi.Config();
const environment = config.require("environment") as "dev" | "prod";

new WebAppInfra("webapp", {
  environment,
  dbInstanceClass: config.require("dbInstanceClass"),
  dbMultiAz: config.getBoolean("dbMultiAz") ?? environment === "prod",
  dbAllocatedStorage: config.getNumber("dbAllocatedStorage") ?? 20,
  dbPassword: config.requireSecret("dbPassword"), // encrypted at rest by Pulumi
  bucketReplicationRegion:
    config.get("bucketReplicationRegion") || undefined,
  // OIDC wiring omitted — pass EKS provider outputs when the cluster stack is added
});

// Exported stack outputs
export const stackConfig = { environment };
```

